#!/usr/bin/env python3
"""OpenStreetMap `opening_hours` strings -> a weekly timetable a planner can test against.

    parse("Mo-Fr 09:00-17:00; Sa 10:00-16:00; Su off")
    -> {"mo": [["09:00", "17:00"]], ..., "sa": [["10:00", "16:00"]], "su": []}

Only the plain weekly subset is read: weekday ranges and lists, time spans,
`off`/`closed`, `24/7`, and rules with no weekday (every day). Later rules
override earlier ones for the days they name, as the OSM specification says.
Public-holiday rules (`PH ...`) say nothing about an ordinary week and are
dropped.

Anything outside that subset — months or dates (`Jun-Jul off`), nth weekdays
(`Tu[1]`), open ends (`14:00+`), sunrise/sunset, `||` fallbacks, quoted
comments — makes the whole string unparsed (None). A partial read would
publish a confident timetable for a place whose real hours depend on the part
that was skipped; unknown is the honest answer, and the raw string is always
served beside it.
"""

import re
import sys

DAYS = ("mo", "tu", "we", "th", "fr", "sa", "su")
_TIME = r"(?:[01]\d|2[0-4]):[0-5]\d"
_SPAN_RE = re.compile(r"^(%s)-(%s)$" % (_TIME, _TIME))
_DAY_RE = re.compile(r"^(Mo|Tu|We|Th|Fr|Sa|Su)(?:-(Mo|Tu|We|Th|Fr|Sa|Su))?$")


def _days(selector):
    """'Mo-Fr,Su' -> ['mo','tu','we','th','fr','su']; None when not a weekday selector."""
    out = []
    for part in selector.split(","):
        m = _DAY_RE.match(part)
        if not m:
            return None
        a = DAYS.index(m.group(1).lower())
        b = DAYS.index((m.group(2) or m.group(1)).lower())
        span = range(a, b + 1) if a <= b else list(range(a, 7)) + list(range(0, b + 1))
        out.extend(DAYS[i] for i in span if DAYS[i] not in out)
    return out


def _spans(text):
    """'09:00-12:00,13:00-17:00' -> [['09:00','12:00'], ['13:00','17:00']]; None when not spans."""
    spans = []
    for part in text.split(","):
        m = _SPAN_RE.match(part.strip())
        if not m:
            return None
        spans.append([m.group(1), m.group(2)])
    return spans


def parse(value):
    if value is None:
        return None
    text = value.strip()
    if text == "24/7":
        return {d: [["00:00", "24:00"]] for d in DAYS}
    if not text or "||" in text or '"' in text:
        return None
    week = {d: [] for d in DAYS}
    for rule in (r.strip() for r in text.split(";")):
        if not rule:
            continue
        if rule.startswith("PH"):
            continue
        head, _, rest = rule.partition(" ")
        days = _days(head)
        if days is None:
            # No weekday selector: the rule is every day, if it is spans at all.
            days, rest = list(DAYS), rule
        rest = rest.strip()
        if rest in ("off", "closed"):
            for d in days:
                week[d] = []
            continue
        spans = _spans(rest.replace(" ", "")) if rest else None
        if spans is None:
            return None
        for d in days:
            week[d] = spans
    return week


def open_at(week, day, hhmm):
    """Is a parsed timetable open on weekday `day` ('mo'..'su') at 'HH:MM'? None when unknown."""
    if week is None:
        return None
    return any(a <= hhmm < b for a, b in week[day])


def selftest():
    assert parse("Mo-Fr 09:00-17:00; Sa 10:00-16:00; Su off") == {
        "mo": [["09:00", "17:00"]], "tu": [["09:00", "17:00"]], "we": [["09:00", "17:00"]],
        "th": [["09:00", "17:00"]], "fr": [["09:00", "17:00"]], "sa": [["10:00", "16:00"]], "su": []}
    # Later rules override earlier ones for the days they name.
    week = parse("Mo-Su 10:00-17:00; Th 10:00-19:00")
    assert week["th"] == [["10:00", "19:00"]] and week["we"] == [["10:00", "17:00"]]
    assert parse("Mo,Su off; Tu-Fr 10:00-17:00; Sa,PH 13:00-17:00") is None  # "Sa,PH" is not a weekday list
    assert parse("Mo,Su off; Tu-Fr 10:00-17:00; PH off")["mo"] == []
    assert parse("08:00-22:00")["su"] == [["08:00", "22:00"]]
    assert parse("24/7")["we"] == [["00:00", "24:00"]]
    assert parse("Mo-Sa 11:00-18:00;Su 12:00-17:00")["su"] == [["12:00", "17:00"]]
    assert parse("Mo-Fr 09:00-12:00,13:00-17:00")["mo"] == [["09:00", "12:00"], ["13:00", "17:00"]]
    assert parse("Fr-Mo 10:00-16:00")["su"] == [["10:00", "16:00"]] and parse("Fr-Mo 10:00-16:00")["tu"] == []
    for unparsed in ("Sa[-1] 10:00-16:00; Jun-Jul off", 'Mo-Fr off || "wider garden opening hours"',
                     "Tu[1] 14:00+", "We-Sa 11:00-17:00; Aug Mo-Sa 11:00-17:00", "sunrise-sunset", "", None):
        assert parse(unparsed) is None, unparsed
    assert open_at(parse("Mo-Fr 09:00-17:00"), "mo", "16:59") is True
    assert open_at(parse("Mo-Fr 09:00-17:00"), "mo", "17:00") is False
    assert open_at(None, "mo", "12:00") is None
    print("opening_hours selftest: ok")


if __name__ == "__main__":
    if sys.argv[1:] != ["--selftest"]:
        sys.exit("usage: opening_hours.py --selftest")
    selftest()

