  columns: ["List", "Draws at most"],
  rows: [
    ["The drawer's programme list", "nothing: it asks for a search"],
    ["A one-letter search's results", "SEARCH_RESULT_ROWS (40)"],
    ["The kinds filter's options", "FACET_OPTIONS (30)"],
